import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { BlockedCommand } from '../types'
import {
  ALLOW_SESSION,
  NO_ANSWER,
  QUESTION_PREFIX,
  REFUSE,
  RUN,
  WAIT_ASK,
  allowKey,
  denyReason,
  failedMessage,
  question,
  ranMessage,
  ranReason,
  refusedMessage,
  refusedReason,
  runFailedReason,
} from './lib'

type $ = EngineInterface

const queue = atom({ plugin: 'blocked-run', key: 'queue' } as const, [])
const runningId = atom({ plugin: 'blocked-run', key: 'runningId' } as const, null)
const allowed = atom({ plugin: 'blocked-run', key: 'allowed' } as const, [])

const RUN_TIMEOUT_MS = 5 * 60 * 1000

const drop = ($: $, id: string) => update($, queue, q => q.filter(item => item.id !== id))

async function run($: $, blocked: BlockedCommand): Promise<void> {
  if ((await read($, runningId)) !== null) return
  await update($, runningId, () => blocked.id)
  let message: string
  try {
    const ran = await $.process.run(['bash', '-c', blocked.command], { cwd: blocked.cwd, timeoutMs: RUN_TIMEOUT_MS })
    message = ranMessage(blocked, ran.exitCode, ran.stdout, ran.stderr)
    $.ui.toast(ran.exitCode === 0 ? '✓ Comando executado' : `Comando terminou com exit ${ran.exitCode}`)
  } catch (error) {
    message = failedMessage(blocked, error instanceof Error ? error.message : String(error))
    $.ui.toast('blocked-run: o comando não rodou', { timeoutMs: 8000 })
  }
  await drop($, blocked.id)
  await update($, runningId, () => null)
  await $.prompt.submit({ text: message, asUser: true })
}

async function allowSession($: $, blocked: BlockedCommand): Promise<string> {
  const key = allowKey(blocked.rule, blocked.command)
  await update($, allowed, keys => (keys.includes(key) ? keys : [...keys, key]))
  $.ui.toast(blocked.rule === null ? 'Comando liberado nesta sessão' : `${blocked.rule} liberado nesta sessão`)

  return key
}

async function refuse($: $, blocked: BlockedCommand): Promise<void> {
  await drop($, blocked.id)
  await $.prompt.submit({ text: refusedMessage(blocked), asUser: true })
}

/**
 * Pergunta no diálogo do próprio Claude Code, com o agente parado na chamada até a
 * resposta. undefined quando não há decisão: diálogo fechado, `-p` ou ausência.
 */
async function decide($: $, blocked: BlockedCommand): Promise<string | undefined> {
  // Why: "Não executar" primeiro, para qualquer escolha padrão cair na recusa.
  const answer = await $.ui.ask(question(blocked), { header: 'Bloqueado', options: [REFUSE, RUN, ALLOW_SESSION] }).catch(() => undefined)

  return answer === undefined || answer === NO_ANSWER ? undefined : answer
}

async function runNow($: $, blocked: BlockedCommand): Promise<string> {
  try {
    const ran = await $.process.run(['bash', '-c', blocked.command], { cwd: blocked.cwd, timeoutMs: RUN_TIMEOUT_MS })
    $.ui.toast(ran.exitCode === 0 ? '✓ Comando executado' : `Comando terminou com exit ${ran.exitCode}`)

    return ranReason(blocked, ran.exitCode, ran.stdout, ran.stderr)
  } catch (error) {
    $.ui.toast('blocked-run: o comando não rodou', { timeoutMs: 8000 })

    return runFailedReason(error instanceof Error ? error.message : String(error))
  }
}

export const register: Register = on => {
  // Só a negação que chega ao agente principal numa chamada real: um subagente não lê a resposta.
  on('tool.check', { tool: 'Bash' }, async ($, e, next) => {
    const verdict = await next(e)
    if (verdict.decision !== 'deny') return verdict
    const command = String((e.input as { command?: unknown } | null)?.command ?? '').trim()
    if (command === '') return verdict
    // O que o usuário liberou para a sessão roda pelo próprio Bash, também num subagente.
    const key = allowKey(verdict.rule ?? null, command)
    if ((await read($, allowed)).includes(key)) return { decision: 'allow', reason: `blocked-run: ${key} liberado nesta sessão` }
    const id = e.tool_use_id
    if (id === undefined || e.agentId !== undefined) return verdict

    const blocked: BlockedCommand = { id, command, cwd: await $.session.cwd(), rule: verdict.rule ?? null }
    const why = denyReason(verdict.reason, verdict.rule)
    const answer = await decide($, blocked)
    if (answer === RUN) return { ...verdict, reason: `${why}. ${await runNow($, blocked)}` }
    if (answer === ALLOW_SESSION) return { decision: 'allow', reason: `blocked-run: ${await allowSession($, blocked)} liberado nesta sessão` }
    if (answer !== undefined) return { ...verdict, reason: `${why}. ${refusedReason(answer)}` }

    await update($, queue, q => (q.some(item => item.id === id) ? q : [...q, blocked]))

    return { ...verdict, reason: `${why}. ${WAIT_ASK}` }
  }).catch(($, e, next) => next(e))

  // O diálogo que se resolveu sozinho por ausência não é decisão: o comando vai para a faixa.
  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    const result = await next(e)
    const answered = (result as { result?: { answers?: Record<string, string>; afkTimeoutMs?: number } }).result
    if (answered?.afkTimeoutMs === undefined || answered.answers === undefined) return result
    const answers = Object.fromEntries(
      Object.entries(answered.answers).map(([asked, answer]) => [asked, asked.startsWith(QUESTION_PREFIX) ? NO_ANSWER : answer]),
    )

    return { ...result, result: { ...answered, answers } } as typeof result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const items = await read($, queue)
    const blocked = items[0]
    if (blocked === undefined || e.props.hasSurvey || e.props.view.agentId) return next(e)
    const isRunning = (await read($, runningId)) === blocked.id
    const { Box, Button, Text } = $.ui.resolve(e)
    const more = items.length > 1 ? ` · +${items.length - 1} na fila` : ''

    return (
      <Box flexDirection="column">
        <Text color="warning">
          ⛔ O agente foi bloqueado{blocked.rule === null ? '' : ` por ${blocked.rule}`}. Executar você mesmo?{more}
        </Text>
        <Box paddingLeft={2} flexDirection="column">
          <Text bold>{blocked.command}</Text>
          <Text dimColor>em {blocked.cwd}</Text>
        </Box>
        {isRunning ? (
          <Text dimColor>Executando…</Text>
        ) : (
          <Box flexDirection="row" gap={1}>
            <Button key="run" label={RUN} variant="primary" hotkey="e" onPress={() => run($, blocked)} />
            <Button key="refuse" label={REFUSE} role="dismiss" hotkey="n" onPress={() => refuse($, blocked)} />
            <Button
              key="session"
              label={ALLOW_SESSION}
              hotkey="p"
              onPress={async () => {
                await allowSession($, blocked)
                await run($, blocked)
              }}
            />
          </Box>
        )}
      </Box>
    )
  })
}

