// Lógica pura do blocked-run, separada para os testes.

import type { BlockedCommand } from '../types'

/** Sem o diálogo (fechado, ausência, `-p`): o comando vai para a faixa, e o agente espera em vez de contornar. */
export const WAIT_ASK =
  'blocked-run: o comando foi oferecido ao usuário num botão, para ele mesmo executar ou recusar. ' +
  'Não tente contorná-lo com outro comando, script ou ferramenta. Se precisar do resultado para continuar, ' +
  'encerre o turno dizendo que aguarda: a decisão e a saída chegam na próxima mensagem do usuário.'

const MAX_OUTPUT = 4000

/** Guarda o fim da saída, onde costuma estar o erro, e diz quanto foi cortado. */
export function tailOf(text: string, max = MAX_OUTPUT): string {
  const trimmed = text.trimEnd()
  if (trimmed.length <= max) return trimmed

  return `[… ${trimmed.length - max} caracteres iniciais omitidos]\n${trimmed.slice(-max)}`
}

export function ranMessage(blocked: BlockedCommand, exitCode: number, stdout: string, stderr: string): string {
  const output = tailOf([stdout.trimEnd(), stderr.trimEnd()].filter(Boolean).join('\n'))

  return [
    `[blocked-run] Executei eu mesmo o comando que estava bloqueado (em ${blocked.cwd}):`,
    '',
    '```bash',
    blocked.command,
    '```',
    '',
    output === '' ? `Terminou com exit ${exitCode}, sem saída.` : `Terminou com exit ${exitCode}. Saída:\n\n\`\`\`\n${output}\n\`\`\``,
    '',
    'Siga a partir daqui.',
  ].join('\n')
}

export function refusedMessage(blocked: BlockedCommand): string {
  return [
    '[blocked-run] Não autorizei o comando bloqueado:',
    '',
    '```bash',
    blocked.command,
    '```',
    '',
    'Siga sem ele, sem tentar contorná-lo; se não houver como, me diga o que falta.',
  ].join('\n')
}

export function failedMessage(blocked: BlockedCommand, error: string): string {
  return [
    '[blocked-run] Tentei executar o comando bloqueado, mas ele não rodou:',
    '',
    '```bash',
    blocked.command,
    '```',
    '',
    `Erro: ${error}`,
  ].join('\n')
}

/** O começo da pergunta do diálogo; o hook de AskUserQuestion reconhece por ele as perguntas do blocked-run. */
export const QUESTION_PREFIX = 'O agente foi bloqueado'
export const RUN = 'Executar'
export const REFUSE = 'Não executar'
export const ALLOW_SESSION = 'Permitir durante esta sessão'
/** A resposta que o diálogo deu sozinho, por ausência: não é decisão, e o comando vai para a faixa. */
export const NO_ANSWER = '(sem resposta)'

export function question(blocked: BlockedCommand): string {
  const rule = blocked.rule === null ? '' : ` por ${blocked.rule}`
  const session = blocked.rule === null ? 'este comando' : `o que ${blocked.rule} negar`

  return `${QUESTION_PREFIX}${rule} neste comando, em ${blocked.cwd}:\n\n${blocked.command}\n\nExecutar você mesmo? "${ALLOW_SESSION}" libera ${session} até o fim da sessão.`
}

/** O que a sessão libera: a regra que negou ou, sem regra, o próprio comando. */
export function allowKey(rule: string | null, command: string): string {
  return rule ?? command
}

/** O motivo da negação, com a regra que negou, que o engine não põe no texto. */
export function denyReason(reason: string | undefined, rule: string | undefined): string {
  if (reason === undefined) return rule === undefined ? 'negado' : `negado pela regra ${rule}`

  return rule === undefined ? reason : `${reason.replace(/\.+$/, '')} (regra ${rule})`
}

/** O que o agente lê quando o usuário executou o comando pelo diálogo, no mesmo turno. */
export function ranReason(blocked: BlockedCommand, exitCode: number, stdout: string, stderr: string): string {
  const output = tailOf([stdout.trimEnd(), stderr.trimEnd()].filter(Boolean).join('\n'))

  return [
    `blocked-run: o usuário executou ele mesmo este comando, em ${blocked.cwd}.`,
    output === '' ? `Terminou com exit ${exitCode}, sem saída.` : `Terminou com exit ${exitCode}. Saída:\n${output}`,
    'Não execute de novo; siga a partir daqui.',
  ].join('\n')
}

export function refusedReason(answer: string): string {
  const said = answer === REFUSE || answer === '' ? '' : ` e respondeu: "${answer}"`

  return `blocked-run: o usuário não autorizou este comando${said}. Siga sem ele, sem tentar contorná-lo com outro comando, script ou ferramenta; se não houver como, diga a ele o que falta.`
}

export function runFailedReason(error: string): string {
  return `blocked-run: o usuário mandou executar este comando, mas ele não rodou. Erro: ${error}. Não tente contorná-lo; diga a ele o que aconteceu.`
}

