/** Um comando Bash do agente que as regras de permissão negaram, à espera da sua decisão. */
export type BlockedCommand = {
  /** O tool_use_id da chamada negada. */
  id: string
  command: string
  /** Onde ele roda se você aprovar: a pasta da sessão. */
  cwd: string
  /** A regra que negou (`Bash(rm *)`), quando o engine diz. */
  rule: string | null
}

declare module 'claude-code' {
  interface PluginState {
    'blocked-run': {
      queue: BlockedCommand[]
      /** O id do comando que está executando agora, ou null. */
      runningId: string | null
      /** As regras (ou, sem regra, os comandos) liberadas até o fim da sessão. */
      allowed: string[]
    }
  }
}
